import{_ as o,o as d,c as a,a3 as t}from"./chunks/framework.DWfJTVRq.js";const p=JSON.parse('{"title":"변경 기록","description":"패키지마다 버전을 따로 매기고 변경 기록도 따로 둡니다. 이 페이지는 모든 패키지의 기록을 최신순으로 보여 줍니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문 그대로입니다.","frontmatter":{"title":"변경 기록","order":1,"editLink":false,"outline":[2,3],"prev":{"text":"타입","link":"/ko/types/"},"next":{"text":"다른 DB에서 옮기기","link":"/ko/migration/"}},"headers":[{"level":2,"title":"Rust 크레이트 darudb","slug":"rust-크레이트-darudb","link":"#rust-크레이트-darudb","children":[{"level":3,"title":"Rust vNext (2026--)","slug":"rust-vnext-2026","link":"#rust-vnext-2026","children":[{"level":4,"title":"Added","slug":"added","link":"#added","children":[]}]}]},{"level":2,"title":"Rust 크레이트 darudb-derive","slug":"rust-크레이트-darudb-derive","link":"#rust-크레이트-darudb-derive","children":[{"level":3,"title":"Rust derive vNext (2026--)","slug":"rust-derive-vnext-2026","link":"#rust-derive-vnext-2026","children":[{"level":4,"title":"Added","slug":"added-1","link":"#added-1","children":[]}]}]},{"level":2,"title":"Node.js 패키지 darudb","slug":"node-js-패키지-darudb","link":"#node-js-패키지-darudb","children":[{"level":3,"title":"Node.js vNext (2026--)","slug":"node-js-vnext-2026","link":"#node-js-vnext-2026","children":[{"level":4,"title":"Added","slug":"added-2","link":"#added-2","children":[]}]}]},{"level":2,"title":"Dart 패키지 darudb","slug":"dart-패키지-darudb","link":"#dart-패키지-darudb","children":[{"level":3,"title":"Dart vNext (2026--)","slug":"dart-vnext-2026","link":"#dart-vnext-2026","children":[{"level":4,"title":"Added","slug":"added-3","link":"#added-3","children":[]}]}]},{"level":2,"title":"Dart 패키지 darudb_generator","slug":"dart-패키지-darudb-generator","link":"#dart-패키지-darudb-generator","children":[{"level":3,"title":"Dart generator vNext (2026--)","slug":"dart-generator-vnext-2026","link":"#dart-generator-vnext-2026","children":[{"level":4,"title":"Added","slug":"added-4","link":"#added-4","children":[]}]}]}],"relativePath":"ko/changelog.md","filePath":"ko/changelog.md","lastUpdated":null}'),c={name:"ko/changelog.md"};function n(i,e,r,s,l,h){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="변경-기록" tabindex="-1">변경 기록 <a class="header-anchor" href="#변경-기록" aria-label="Permalink to &quot;변경 기록&quot;">​</a></h1><p>패키지마다 버전을 따로 매기고 변경 기록도 따로 둡니다. 이 페이지는 모든 패키지의 기록을 최신순으로 보여 줍니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문 그대로입니다.</p><h2 id="rust-크레이트-darudb" tabindex="-1">Rust 크레이트 <code>darudb</code> <a class="header-anchor" href="#rust-크레이트-darudb" aria-label="Permalink to &quot;Rust 크레이트 `darudb`&quot;">​</a></h2><h3 id="rust-vnext-2026" tabindex="-1">Rust vNext (2026--) <a class="header-anchor" href="#rust-vnext-2026" aria-label="Permalink to &quot;Rust vNext (2026--)&quot;">​</a></h3><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database::open</code> and <code>OpenOptions</code> open a database file, creating it when nothing exists at the path. A new file appears whole or not at all, even when two processes create it at once. Its page size is a power of two from 4096 to 65536, and the file&#39;s header is validated every time it is opened again.</li><li><code>Database::begin_read</code> and <code>Database::begin_write</code> start transactions over named trees of byte keys and byte values. <code>ReadTransaction</code> sees one commit for as long as it lives, whatever is committed after it began. <code>WriteTransaction</code> adds <code>insert</code>, <code>remove</code> and <code>delete_tree</code>, sees its own changes, and makes all of them visible and durable at once with <code>commit</code>; dropping it aborts it. Both offer <code>get</code>, <code>range</code>, <code>range_backward</code>, <code>iter</code>, <code>len</code> and <code>tree_names</code>.</li><li>A commit is durable when <code>commit</code> returns: a crash or a power cut at any moment leaves the file at a commit no older than the last one that returned. Opening a file after a crash recovers it without a separate step.</li><li>Every page is verified against the check its parent recorded before it is used, so a damaged or stale page is reported as <code>CORRUPTED</code> rather than read.</li><li>A value too large to keep in a tree&#39;s pages is stored in pages of its own, up to 4 GiB.</li><li><code>Database</code> handles to one file in a process share one instance, so they see the same commits and take turns writing. <code>OpenOptions::busy_timeout</code> sets how long <code>begin_write</code> waits for another writer.</li><li><code>Error</code> reports every failure with a stable <code>code</code>: <code>IO</code>, <code>NOT_FOUND</code>, <code>NOT_A_DATABASE</code>, <code>UNSUPPORTED_FORMAT_VERSION</code>, <code>CORRUPTED</code>, <code>INVALID_ARGUMENT</code>, <code>CLOSED</code>, <code>BUSY</code>, <code>SYNC_FAILED</code> and <code>INTERNAL</code>. <code>CLOSED</code> is for a language binding&#39;s handle used after it was closed; <code>SYNC_FAILED</code> means a barrier failed, the last commit&#39;s outcome is unknown, and the file has to be opened again.</li><li><code>WriteTransaction::commit_deferred</code> publishes a commit without waiting for a barrier. Readers see it at once; it becomes durable at the next <code>commit</code>, at <code>Database::sync</code>, when the database is closed, or when <code>OpenOptions::max_unsynced_time</code> (one second by default) or <code>OpenOptions::max_unsynced_pages</code> runs out. A crash of the process loses no deferred commit, and a power cut undoes them only from the newest backwards. Pages that deferred commits write and stop using again are reused before the window ends once no reader needs them, so a run of small deferred commits does not grow the file.</li><li><code>Database::close</code> makes deferred commits durable first, and reports whether a barrier failed on any handle to the file.</li><li><code>OpenOptions::key</code> and <code>OpenOptions::password</code> create an encrypted database, or open one. Every page is encrypted and authenticated under a random data key, which the key, or the Argon2id hash of the password, wraps: with XAES-256-GCM on processors with AES instructions, and XChaCha20-Poly1305 elsewhere. <code>OpenOptions::password_hashing</code> sets the Argon2id cost, 19 MiB, 2 iterations and 1 lane by default.</li><li>Each commit record of an encrypted database carries a MAC under a key derived from the data key, so a record put together from the file&#39;s own pages by someone without the key is refused. The file format version is 3.</li><li><code>Database::set_key</code> and <code>Database::set_password</code> change the key of an encrypted database without encrypting any page again, and <code>Database::is_encrypted</code> tells the two kinds of database apart.</li><li>The error codes <code>KEY_REQUIRED</code>, for an encrypted database opened without a key or password, and <code>WRONG_KEY</code>, for one that does not open it.</li><li>Several processes can open one database file at once, coordinated through the operating system&#39;s byte-range locks and nothing else. One process writes at a time and <code>begin_write</code> waits for another process&#39;s writer as it does for its own, readers never wait for a writer, and a process that dies releases its locks with nothing left for the others to clean up. The first process to open a file recovers it, and one that opens it meanwhile waits up to the busy timeout. <code>Database::sync</code> makes deferred commits durable whichever process made them.</li><li>The error code <code>UNSUPPORTED_FILE_SYSTEM</code>, for a database on a network file system such as NFS or SMB, or on one whose file locks do not work. Network file systems are recognised on Linux, Android, macOS, iOS and Windows, on a best-effort basis, and a new database is refused before its file is created.</li><li>Collections of typed objects. <code>OpenOptions::schema</code> declares a <code>Schema</code> of <code>Collection</code>s, each with fields of a <code>Type</code>, a primary key that is a declared field or an auto-increment, and indexes, unique or not. The first open stores the schema in the file, and every later open compares it with the stored one. <code>ReadTransaction::collection</code> and <code>WriteTransaction::collection</code> read and write <code>Object</code>s of <code>Value</code>s: <code>insert</code>, <code>put</code>, <code>delete</code>, <code>get</code>, <code>iter</code> and <code>len</code>, with every index kept in step in the same transaction. A write the schema or a unique index refuses leaves the transaction able to commit.</li><li>Migrations. A schema carries a version, and opening a file that holds an older one migrates it in one write transaction: the engine adds collections, fields and indexes and removes what the schema no longer has, and a <code>Migration</code> registered with <code>OpenOptions::migration</code> renames collections and fields, replaces fields, deletes collections, and runs a function that moves data, reading the old objects through <code>Migrating::previous</code>.</li><li>Queries. <code>CollectionReader::query</code> and <code>CollectionWriter::query</code> return the objects a <code>Query</code> finds, and <code>count</code> counts them. A <code>Filter</code> tests fields, fields of embedded objects and fields of linked objects with comparisons, <code>between</code>, <code>is_in</code>, <code>contains</code>, <code>starts_with</code>, <code>ends_with</code> and null tests, combined with <code>and</code>, <code>or</code> and <code>!</code>; a query sorts by any number of fields and takes an offset and a limit. A condition on the primary key or an indexed field reads only the objects that meet it, and a sort on an indexed field alone stops reading at the limit. The error code <code>INVALID_QUERY</code> reports a query that names a missing field or compares a field with a value of another type.</li><li><code>Query::parse</code> reads a query written in the query language, such as <code>age &gt;= $0 AND name STARTSWITH &quot;A&quot; SORT BY age DESC LIMIT 10</code>, with parameters for <code>$0</code>, <code>$1</code> and on, into the same query the builder makes. Text that does not parse fails with <code>INVALID_QUERY</code>, naming the character where it went wrong.</li><li><code>OpenOptions::cache_size</code> sets how much memory the page cache of a file may take, in bytes: 32 MiB by default, and never fewer than 16 pages. The cache fills only as pages are read.</li><li><code>Query::prepare</code> parses a query once and keeps its parameters, and <code>Query::bind</code> gives them values, for a query that runs many times; <code>Query::bind_encoded</code> takes them encoded in one record, as a language binding sends them. A query run with a parameter that has no value fails with <code>INVALID_QUERY</code>.</li><li>The byte formats language bindings exchange with the engine: <code>CollectionReader::get_record</code>, <code>CollectionWriter::insert_record</code> and <code>put_record</code>, and <code>query_records</code> carry objects as records, which <code>get_record_with</code> and <code>query_records_with</code> lend where they lie rather than copying each into a vector; <code>QueryRequest</code> reads and writes a query as IR; <code>Database::schema_record</code> gives the stored schema as its record; and <code>Schema::decode</code> reads a schema declared in another language.</li><li><code>Query::first</code> keeps only the first object a query finds, and stops reading there.</li><li><code>OpenOptions::open_migrating</code> opens a database whose migration stops for the caller between its version steps, as a <code>PendingMigration</code>, so that a binding can run migration functions written in its own language in the migration&#39;s write transaction. <code>PendingMigration::previous_schema_record</code> and <code>Migrating::previous_record</code> give a binding the old schema and the old objects as records, and <code>PendingMigration::schema_record</code> and <code>transaction</code> the new schema and the migration&#39;s write transaction.</li><li>The error codes <code>SCHEMA_MISMATCH</code>, for a schema changed without a new version or a file migrated under an open handle, <code>SCHEMA_TOO_NEW</code>, for a file a newer application wrote, <code>DUPLICATE_KEY</code> and <code>MIGRATION_FAILED</code>. <code>UNSUPPORTED_FORMAT_VERSION</code> also reports a stored schema in an object format a newer build wrote.</li><li><code>CollectionWriter::update</code> sets the fields it is given in the object with a key and keeps the rest, going down the collection&#39;s tree once, and returns whether there was an object. The object becomes what <code>put</code> would write for the stored object with those fields set: <code>Value::Null</code> makes an optional field null and gives a field with a default its default. Changing the primary key fails with <code>INVALID_ARGUMENT</code>. <code>CollectionWriter::update_record</code> takes the changes as a record, as a language binding sends them, in which the tag <code>0x01</code> makes a field null; in a collection whose fields all hold scalars it changes the stored record where it lies and reads only the indexes on the fields it changes.</li><li><code>Database::check</code>, the integrity check: every page the published commit reaches against its check, the order of every key, every tree&#39;s count, that every page of the file is used, free or retained exactly once, and in a file with a schema every object against its indexes. It returns a <code>CheckReport</code> of every <code>Problem</code> it finds, and reads the commit a read transaction sees, so other handles and processes may write meanwhile.</li><li><code>Database::backup</code>, a copy of the published commit in a new file, written while other handles and processes go on using the database. The copy holds no free space, has the file&#39;s page size, and opens with the same key or password. It appears at the path only once it is whole and durable, and never replaces a file already there. It returns a <code>BackupReport</code>.</li><li><code>Database::compact</code>, which makes the file smaller in place, while other handles and processes go on using it: write transactions move the pages at the end of the file into free pages nearer its start, and the commits after them give the end back to the file system. It returns a <code>CompactReport</code>.</li><li><code>OpenOptions::salvage</code>, which rescues what it can of a damaged file into a new one. It reads the file page by page, so it works on a file that does not open, starts from the newest commit it records, and takes what that commit cannot read from older versions of the same pages where the file still has them. The new file gets its indexes built again from its objects, passes the integrity check, and opens with the same key or password. It needs the file alone, so an open file fails with <code>BUSY</code>, and it returns a <code>SalvageReport</code> of what it rescued and what it could not.</li><li>Objects as Rust types. With the <code>derive</code> feature, <code>#[derive(Object)]</code> makes a struct the objects of a collection and <code>#[derive(Embedded)]</code> makes one an embedded object, with <code>#[darudb(...)]</code> attributes for the key, indexes, field names and defaults. <code>Collection::of</code> declares the collection from the type, and <code>ReadTransaction::collection_of</code>, <code>WriteTransaction::collection_of</code> and <code>Migrating::collection_of</code> give a <code>TypedReader</code> or <code>TypedWriter</code> that reads records straight into the type and writes it as records, without building an <code>Object</code>. <code>Link&lt;T&gt;</code> is a link typed by its target. The traits <code>CollectionType</code>, <code>EmbeddedType</code>, <code>FieldType</code>, <code>ElementType</code> and <code>KeyType</code>, with <code>FieldReader</code>, <code>ValueReader</code> and <code>ValueWriter</code>, can be implemented by hand without the feature. A type whose fields do not match the stored collection fails with <code>INVALID_ARGUMENT</code>.</li></ul><h2 id="rust-크레이트-darudb-derive" tabindex="-1">Rust 크레이트 <code>darudb-derive</code> <a class="header-anchor" href="#rust-크레이트-darudb-derive" aria-label="Permalink to &quot;Rust 크레이트 `darudb-derive`&quot;">​</a></h2><h3 id="rust-derive-vnext-2026" tabindex="-1">Rust derive vNext (2026--) <a class="header-anchor" href="#rust-derive-vnext-2026" aria-label="Permalink to &quot;Rust derive vNext (2026--)&quot;">​</a></h3><h4 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>#[derive(Object)]</code>, which implements <code>darudb::CollectionType</code> for a struct with named fields, and <code>#[derive(Embedded)]</code>, which implements <code>darudb::EmbeddedType</code> and <code>darudb::FieldType</code>. They read <code>#[darudb(collection = &quot;...&quot;)]</code> on the struct, and <code>key</code>, <code>index</code>, <code>unique</code>, <code>rename = &quot;...&quot;</code> and <code>default = ...</code> on a field.</li></ul><h2 id="node-js-패키지-darudb" tabindex="-1">Node.js 패키지 <code>darudb</code> <a class="header-anchor" href="#node-js-패키지-darudb" aria-label="Permalink to &quot;Node.js 패키지 `darudb`&quot;">​</a></h2><h3 id="node-js-vnext-2026" tabindex="-1">Node.js vNext (2026--) <a class="header-anchor" href="#node-js-vnext-2026" aria-label="Permalink to &quot;Node.js vNext (2026--)&quot;">​</a></h3><h4 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database.open</code> opens a database file, creating it when nothing exists at the path, with <code>create</code> and <code>pageSize</code> options. <code>path</code>, <code>isOpen</code>, <code>pageSize</code> and <code>formatVersion</code> describe the open database, and <code>close</code> flushes and closes it.</li><li>Every error thrown by the package carries the engine&#39;s stable <code>code</code>, such as <code>NOT_FOUND</code>, <code>NOT_A_DATABASE</code> or <code>CLOSED</code>.</li><li>Several processes can open one database file at once, coordinated through the engine&#39;s file locks. A database on a network file system is refused with <code>UNSUPPORTED_FILE_SYSTEM</code>.</li><li><code>engineVersion()</code> and <code>FORMAT_VERSION</code> report the engine inside the package and the file format version it reads and writes.</li><li>Collections of objects under a schema declared with <code>t</code>, <code>collection</code> and <code>schema</code>, passed to <code>Database.open</code> as <code>schema</code>. TypeScript infers every object&#39;s type from the declaration. <code>db.read(fn)</code> and <code>db.write(fn)</code> run a function in a transaction, committing a write when the function returns and aborting it when it throws, with <code>durability: &#39;deferred&#39;</code> to commit without waiting for the disk. A collection offers <code>get</code>, <code>find</code>, <code>findOne</code>, <code>count</code>, <code>insert</code>, <code>insertMany</code>, <code>put</code>, <code>putMany</code> and <code>delete</code>, and objects cross into the engine as records, a batch in one call. A property the schema does not have is refused, and so is a modifier on a list&#39;s element, such as <code>t.list(t.string().index())</code>, rather than dropped: an index goes on the list itself. <code>t.bigint()</code> declares an int read as a <code>bigint</code>, write transactions on one file do not nest, even through two <code>Database</code> objects or from a migration function, and <code>busyTimeout</code> sets how long a write waits for another process.</li><li>Queries built with <code>where</code>, <code>sortBy</code>, <code>limit</code> and <code>offset</code>, typed by the collection&#39;s fields, or written in the query language with parameters. <code>conditions</code> and <code>Query</code> build filters outside a collection.</li><li>The <code>cacheSize</code> option of <code>Database.open</code> and <code>Database.openAsync</code> sets how much memory the page cache of a file may take, in bytes: 32 MiB by default.</li><li>Prepared queries: <code>db.prepare(collection, query)</code> parses a query once, as text or built with <code>param</code> in place of values, and <code>find</code>, <code>findOne</code> and <code>count</code> run it with its parameters&#39; values, in synchronous and asynchronous transactions. The package also keeps up to 256 texts it has parsed, so a text query run again with other parameters is not parsed again.</li><li>Migrations: raising the schema&#39;s version migrates the file when it opens, with the renames, deletions and replaced fields a migration lists and a JavaScript function that reads the objects as they were through <code>previous</code> and <code>previousKeys</code>.</li><li><code>db.schemaVersion</code>, and <code>db.sync()</code> to make deferred commits durable.</li><li>The package is written in TypeScript, and its type declarations are generated from its source. They name the types of <code>t</code>, <code>Database</code> and <code>Query</code> as <code>TypeBuilders</code>, <code>DatabaseOpener</code> and <code>QueryConstructor</code>.</li><li>An asynchronous API: <code>Database.openAsync</code>, <code>readAsync</code>, <code>writeAsync</code>, <code>syncAsync</code> and <code>closeAsync</code> do the engine&#39;s work on the libuv thread pool and resolve promises, so the event loop never waits for the disk or for another process&#39;s writer. Their transaction functions and migration functions may be asynchronous, every collection method returns a promise, and a transaction runs its operations in the order they were called and commits once they have all settled. Operations called together, or while earlier ones are on the pool, cross into the engine as one batch in one trip, and <code>readAsync</code> begins its read on the calling thread, since a read waits for no writer. This process&#39;s writes on one file queue in JavaScript rather than on the pool, however each handle named the file, a hard link on Windows included, <code>syncAsync</code> and <code>closeAsync</code> with them, and a synchronous <code>write</code>, <code>sync</code> or <code>close</code> while an asynchronous write holds the file fails with <code>INVALID_ARGUMENT</code> rather than blocking the event loop.</li><li><code>update(key, changes)</code> on the collections of synchronous and asynchronous write transactions sets the fields it is given, keeps the rest, and says whether there was an object. <code>null</code> makes an optional field null and gives a field with a default its default, and a field left <code>undefined</code> stays as it is. Only the changed fields cross into the engine, which changes the stored record where it lies, so updating a field costs less than reading the object and putting it back.</li><li><code>db.check()</code> and <code>db.checkAsync()</code>, the integrity check of the published commit, which report every problem they find, each with its page and its tree or collection, rather than throwing.</li><li><code>db.backup(path)</code> and <code>db.backupAsync(path)</code>, a copy of the published commit in a new file, which the same key or password opens and which never replaces a file already at the path.</li><li><code>db.compact()</code> and <code>db.compactAsync()</code>, which make the file smaller in place. Like a write, <code>compactAsync</code> waits its turn after this process&#39;s other writes on the file, and <code>compact</code> is refused while one of them holds it.</li><li><code>Database.salvage(from, into)</code> and <code>Database.salvageAsync(from, into)</code>, which rescue what they can of a damaged file into a new one, and report what they rescued and what they could not. They work on a file that does not open, need it alone, so a file in use fails with <code>BUSY</code>, and never replace a file already at <code>into</code>.</li><li>Encryption: <code>key</code> or <code>password</code> in the options of <code>open</code>, <code>openAsync</code> and <code>Database.salvage</code> encrypts a new database or opens an encrypted one, <code>passwordHashing</code> sets the cost of hashing a password, <code>db.isEncrypted</code> tells the two kinds of file apart, and <code>setKey</code>, <code>setPassword</code> and their <code>Async</code> twins change the key. Opening an encrypted database without its key fails with <code>KEY_REQUIRED</code>, and with another one with <code>WRONG_KEY</code>.</li><li>Electron&#39;s main process is supported, and the tests run the package there, in Electron 44. The guide says how several Electron processes share one file and how to keep the addon outside an <code>asar</code> archive.</li><li>Every platform package ships <code>LICENSE</code> and <code>THIRD_PARTY_NOTICES.txt</code>, the licences of the Rust crates and of the C source linked into its addon.</li></ul><h2 id="dart-패키지-darudb" tabindex="-1">Dart 패키지 <code>darudb</code> <a class="header-anchor" href="#dart-패키지-darudb" aria-label="Permalink to &quot;Dart 패키지 `darudb`&quot;">​</a></h2><h3 id="dart-vnext-2026" tabindex="-1">Dart vNext (2026--) <a class="header-anchor" href="#dart-vnext-2026" aria-label="Permalink to &quot;Dart vNext (2026--)&quot;">​</a></h3><h4 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database.open</code> opens or creates a database file, with a <code>Schema</code> of the collections <code>darudb_generator</code> generates from classes annotated <code>@Collection()</code> and <code>@Embedded()</code>, and the options <code>create</code>, <code>pageSize</code>, <code>busyTimeout</code>, <code>cacheSize</code>, <code>key</code>, <code>password</code> and <code>passwordHashing</code>. A file holding an older schema version is migrated in one write transaction, through the <code>Migration</code>s registered for the versions in between, whose functions read the old objects through <code>MigrationContext</code>.</li><li><code>Database.read</code> and <code>Database.write</code> run a function in a transaction; <code>write</code> commits when it returns, deferred with <code>Durability.deferred</code>, and aborts when it throws. <code>txn.collection(userSchema)</code> gives a collection&#39;s objects as the annotated class: <code>get</code>, <code>find</code>, <code>findOne</code> and <code>count</code> with a typed query builder whose conditions combine with <code>&amp;</code>, <code>|</code> and <code>~</code>, <code>findText</code> for the query language, <code>Database.prepare</code> and <code>findPrepared</code>, and in a write <code>insert</code>, <code>insertMany</code>, <code>put</code>, <code>putMany</code>, <code>update</code> and <code>delete</code>. <code>update</code> takes a change for each field it sets, made by the field&#39;s <code>set</code>, an embedded object&#39;s included, which it replaces whole.</li><li><code>Database.sync</code>, <code>Database.close</code>, <code>setKey</code>, <code>setPassword</code>, <code>isEncrypted</code>, <code>pageSize</code>, <code>formatVersion</code> and <code>schemaVersion</code>. Every failure is a <code>DaruException</code> with the engine&#39;s error code.</li><li>The <code>Future</code> API: <code>Database.openAsync</code>, <code>readAsync</code>, <code>writeAsync</code>, <code>syncAsync</code>, <code>closeAsync</code>, <code>setKeyAsync</code> and <code>setPasswordAsync</code>, whose transactions give collections of <code>Future</code>-returning calls. The engine&#39;s work runs on threads of the native library, and the result comes back on the isolate&#39;s event loop. The calls of one transaction run in the order they were made; an isolate&#39;s asynchronous writes on one file take turns, and a synchronous <code>write</code>, <code>sync</code> or <code>close</code> on the file while one runs is refused with <code>INVALID_ARGUMENT</code>.</li><li>The tools, each with an <code>Async</code> twin: <code>check</code>, the integrity check, which reports every problem in a <code>CheckReport</code>; <code>backup</code>, a copy of the published commit in a new file; <code>compact</code>, which makes the file smaller in place; and <code>Database.salvage</code>, which rescues what it can of a damaged file into a new one, with a key or a password for an encrypted file.</li><li>The build hook downloads the native library for the application&#39;s target from the package&#39;s GitHub release, and uses it only when its SHA-256 hash is the one <code>hook/prebuilt.json</code> names, so building an application needs no Rust toolchain. A download is kept in the hook&#39;s cache. In a checkout of the repository, which an application gets by depending on the package through git or a path, the hook builds the engine from source with <code>native_toolchain_rust</code> instead.</li></ul><h2 id="dart-패키지-darudb-generator" tabindex="-1">Dart 패키지 <code>darudb_generator</code> <a class="header-anchor" href="#dart-패키지-darudb-generator" aria-label="Permalink to &quot;Dart 패키지 `darudb_generator`&quot;">​</a></h2><h3 id="dart-generator-vnext-2026" tabindex="-1">Dart generator vNext (2026--) <a class="header-anchor" href="#dart-generator-vnext-2026" aria-label="Permalink to &quot;Dart generator vNext (2026--)&quot;">​</a></h3><h4 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>The builder <code>darudb</code>, which writes for each class annotated <code>@Collection()</code> its schema constant, record codec, query builder, link type and <code>copyWith</code>, and for each class annotated <code>@Embedded()</code> its schema constant, codec, query fields and <code>copyWith</code>, into the library&#39;s <code>.g.dart</code> part. It refuses a class it cannot store with an error that names the field: a field that is not final, a type the database does not store, a nullable field with a default, two primary keys, a collection without a key and without <code>int? id</code>, or an index inside an embedded object.</li></ul>',22)])])}const f=o(c,[["render",n]]);export{p as __pageData,f as default};
